const results = $("Search AI News").first().json.results;

let formattedNews = results.map((item, index) => {
  return `${index + 1}. Title: ${item.title}\nURL: ${item.url}\nContent Snippet: ${item.content}\n`;
}).join("\n---\n");

return [{ json: { newsData: formattedNews } }];

let raw = $("Summarize News").first().json.text;

raw = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

const articles = JSON.parse(raw);

const today = new Date().toLocaleDateString("en-US", {
  weekday: "long",
  year: "numeric",
  month: "long",
  day: "numeric"
});

let htmlBody = `
<div style="
font-family:Arial,sans-serif;
max-width:700px;
margin:auto;
background:#f4f6fb;
padding:30px;
">

<div style="
background:#2563eb;
color:white;
padding:30px;
border-radius:12px;
text-align:center;
">

<h1>🤖 Daily AI Digest</h1>

<p>${today}</p>

<p>Top AI developments from the last 24 hours</p>

</div>

<br>
`;

articles.forEach((art, idx) => {

htmlBody += `
<div style="
margin-bottom:25px;
padding:18px;
background:#ffffff;
border-radius:10px;
border-left:6px solid #2563eb;
box-shadow:0 2px 8px rgba(0,0,0,.08);
">

<div style="font-size:14px;color:#666;margin-bottom:10px;">
🔥 <b>${art.importance}/10</b>
&nbsp;&nbsp;|&nbsp;&nbsp;
📂 <b>${art.category}</b>
&nbsp;&nbsp;|&nbsp;&nbsp;
📰 ${art.source}
</div>

<h2 style="margin:0 0 10px 0;">
<a href="${art.url}" style="color:#2563eb;text-decoration:none;">
${idx + 1}. ${art.title}
</a>
</h2>

<p style="font-size:15px;line-height:1.6;">
${art.summary}
</p>

<p style="
background:#eef6ff;
padding:12px;
border-radius:8px;
margin-top:12px;
">
💡 <b>Why it matters</b><br>
${art.impact}
</p>

<p style="margin-top:15px;">
<a href="${art.url}">
Read Full Article →
</a>
</p>

</div>
`;

});

htmlBody += `
<hr>

<p style="
font-size:13px;
color:#777;
text-align:center;
">

Generated automatically using <b>n8n</b> • <b>Tavily</b> • <b>OpenAI</b>

</p>

</div>
`;

return [
  {
    json: {
      htmlBody
    }
  }
];
